le=\\"Gros titre\\" data-customize-website-views=\\"website.template_footer_headline\\" data-customize-website-variable=\\"'headline'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_headline.svg\\"/>\\n        </we-select>\\n        <!-- Colors -->\\n        <we-colorpicker string=\\"Couleurs\\" data-customize-website-color=\\"\\" data-color=\\"footer\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"footer-custom\\" data-layer-gradient=\\"footer-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n        <we-select string=\\"Effet coulissant\\" data-variable=\\"footer-effect\\" data-reload=\\"/\\">\\n            <we-button string=\\"Régulier\\" data-customize-website-views=\\"\\" data-customize-website-variable=\\"\\"/>\\n            <we-button string=\\"Survoler\\" data-customize-website-views=\\"website.template_footer_slideout\\" data-customize-website-variable=\\"'slideout_slide_hover'\\"/>\\n            <we-button string=\\"Ombre\\" data-customize-website-views=\\"website.template_footer_slideout\\" data-customize-website-variable=\\"'slideout_shadow'\\"/>\\n        </we-select>\\n        <we-checkbox string=\\"Copyright\\" data-name=\\"footer_copyright_opt\\" data-customize-website-views=\\"website.footer_no_copyright|\\" data-no-preview=\\"true\\" data-reload=\\"/\\"/>\\n        <we-checkbox string=\\"Sélection de langue\\" data-dependencies=\\"!footer_copyright_opt\\" data-customize-website-views=\\"website.footer_no_copyright|portal.footer_language_selector\\" data-no-preview=\\"true\\" data-reload=\\"/\\"/>\\n    </div>\\n\\n    <!-- Footer - Borders & Shadows -->\\n    <div data-js=\\"Box\\" data-selector=\\"#wrapwrap &gt; footer\\" data-target=\\"#footer\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <t t-call=\\"website.snippet_options_border_widgets\\"/>\\n        <t t-c